  chapter('Le territoire sémantique', 'Le vocabulaire propriétaire de Tiziana, son ton, et sa manière de traiter l’incertitude et la polémique.', null, 'craie')
  page('craie', `${K('Territoire sémantique · proposition')}<h1>Quatre champs lexicaux</h1>
    <div class="grid g4" style="margin-top:8mm">${[['Décision', ['décision', 'arbitrage', 'anticipation', 'conséquence', 'responsabilité', 'trajectoire', 'priorité']], ['Cohérence', ['structure', 'organisation', 'articulation', 'équilibre', 'environnement', 'interdépendance', 'continuité']], ['Réalité', ['condition', 'contrainte', 'implication', 'risque', 'exposition', 'vérification', 'réalité opérationnelle']], ['International', ['juridiction', 'résidence', 'implantation', 'mobilité', 'flux', 'activité', 'développement international']]].map(([t, w], i) => `<div style="background:${i === 2 ? '#702B40' : '#302820'};color:#F2ECE4;border-radius:1.5mm;padding:6mm"><div style="font:500 20pt/1 Fraunces">${t}</div>${mark('underline', 70, 9, 'display:block;margin:3mm 0 4mm', i === 2 ? C.craie : C.grenat)}${w.map((x, k) => `<div style="font:${k ? 400 : 600} ${11 - k * 0.3}pt/1.7 Inter;color:${k ? '#E7DED2' : '#fff'}">${x}</div>`).join('')}</div>`).join('')}</div>
    <h3 style="margin-top:8mm">Expressions récurrentes proposées</h3><div class="grid g5">${['« Avant de regarder les avantages, regardons les conditions. »', '« Ce que cela implique réellement. »', '« Le point qu’il ne faut pas négliger. »', '« Une décision n’est jamais isolée. »', '« Regardons ce qui se passe derrière. »'].map((x) => `<div class="quote" style="font-size:11pt">${x}</div>`).join('')}</div>`, { chap })
  page('craie', `${K('Langage verbal')}<h1>Précis, calme, exigeant, accessible, affirmé</h1>
    <div class="grid g3" style="margin-top:8mm">
    <div class="card"><h4>Mots à privilégier</h4><p>condition · implication · vérifier · cohérence · arbitrage · réalité opérationnelle · anticiper · conséquence · situation · critère</p><h4 style="margin-top:5mm">Mots à éviter</h4><p class="muted">optimiser (seul) · hack · astuce · secret · liberté totale · zéro impôt · paradis · facile · garanti · « il suffit de »</p></div>
    <div class="card"><h4>Rythme et niveau</h4><p><b>Phrases :</b> courtes pour affirmer (8 à 14 mots), une phrase plus longue pour expliquer, jamais deux de suite.<br><b>Niveau :</b> soutenu sans jargon ; tout terme technique est expliqué en une phrase.<br><b>Personne :</b> « je » pour la vision, « nous » uniquement quand elle parle du cabinet.</p></div>
    <div class="card"><h4>Polémique et incertitude</h4><p><b>Polémique :</b> elle ne répond pas à chaud, ne vise jamais une personne, reformule le sujet en conditions et en critères.<br><b>Incertitude :</b> elle la dit clairement — « Le texte n’est pas encore appliqué », « Cela dépend de votre situation », « Un expert du cabinet précisera ce point ».</p></div></div>
    <div class="grid g2" style="margin-top:7mm"><div class="box"><h3>Exemple — à éviter</h3><p class="muted">« Partez à Dubaï, zéro impôt, c’est le secret que les riches ne vous disent pas ! »</p></div><div class="box" style="background:#fff"><h3>Exemple — dans la voix de Tiziana</h3><p>« Avant de regarder le taux d’imposition, regardons les conditions : où vous vivez, où vous décidez, où sont vos clients. Une décision n’est jamais isolée. »</p></div></div>`, { chap })

