  chapter('La palette The Red Mark', 'Le beige comme univers, l’espresso comme autorité, le grenat comme signature.', null, 'esp')
  const PAL = [['Beige craie', C.craie, 'Univers dominant : fonds, papier, murs', '55 %'], ['Sable', C.sable, 'Variations de fond, cartouches, matières', ''], ['Espresso', C.espresso, 'Profondeur, autorité, texte, photos sombres', '30 %'], ['Grenat profond', C.grenat, 'Signature : le trait, le folio, le point clé', '10 %'], ['Bronze', C.bronze, 'Secondaire : rubriques, filets, détails', '5 %']]
  page('craie', `${K('Couleurs · planche colorimétrique')}<h1>Cinq couleurs, une hiérarchie</h1>
    <div class="grid g5" style="margin-top:8mm;gap:4mm">${PAL.map(([n, h, u]) => `<div><div class="sw" style="height:58mm;background:${h};box-shadow:inset 0 0 0 .2mm rgba(0,0,0,.1);position:relative">${h === C.grenat ? mark('horizontal', 120, 14, 'position:absolute;left:8mm;bottom:8mm', C.craie) : ''}</div><div style="font:500 13pt Fraunces;margin-top:3mm">${n}</div><div style="font:600 8pt Manrope;letter-spacing:.1em;color:#9B8267">${h}</div><p style="font-size:8.4pt;margin-top:1.5mm">${u}</p></div>`).join('')}</div>
    <h3 style="margin-top:8mm">Répartition indicative</h3><div style="display:flex;height:12mm;border-radius:1mm;overflow:hidden">${[[C.craie, 35], [C.sable, 20], [C.espresso, 30], [C.grenat, 10], [C.bronze, 5]].map(([c, w]) => `<div style="width:${w}%;background:${c};display:flex;align-items:center;justify-content:center;font:700 7pt Manrope;color:${c === C.espresso || c === C.grenat ? '#F2ECE4' : '#302820'}">${w} %</div>`).join('')}</div>
    <p class="cap">Craie + sable 55 % · espresso et photographies sombres 30 % · grenat 10 % · bronze 5 %. Le bleu institutionnel de Fynovates n’entre pas dans l’identité personnelle, sauf dans un contenu co-signé avec le cabinet.</p>`, { chap })
  const PAIRS = [[C.espresso, C.craie], [C.grenat, C.craie], [C.craie, C.espresso], [C.ivoire, C.grenat], [C.sable, C.espresso], [C.bronze, C.craie]]
  page('craie', `${K('Couleurs · associations, contrastes, dégradés, textures')}<h1>Bien associer</h1>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10mm;margin-top:7mm">
    <div><h3>Contrastes (texte sur fond)</h3><div class="grid g3" style="gap:3mm">${PAIRS.map(([f, b]) => { const r = ratio(f, b); return `<div style="background:${b};color:${f};border-radius:1.2mm;padding:4mm;box-shadow:inset 0 0 0 .2mm rgba(0,0,0,.08)"><div style="font:500 16pt Fraunces">Aa</div><div style="font:600 7pt Manrope;margin-top:1mm">${r.toFixed(1)} : 1 · ${r >= 7 ? 'AAA' : r >= 4.5 ? 'AA' : r >= 3 ? 'grands titres' : 'décor seul'}</div></div>` }).join('')}</div>
    <p class="cap">Ratios calculés selon WCAG 2.1. Le bronze sur craie est réservé aux rubriques et aux grands corps.</p>
    <h3 style="margin-top:6mm">Dégradés autorisés</h3><div class="grid g3" style="gap:3mm">${[['Craie → sable', `linear-gradient(160deg,${C.craieClair},${C.sable})`], ['Espresso profond', `radial-gradient(110% 90% at 25% 15%,#4A3E33,${C.espresso} 45%,${C.espressoProfond})`], ['Grenat cuir', `radial-gradient(120% 90% at 30% 20%,${C.grenatClair},${C.grenat} 55%,#4A1B2A)`]].map(([n, g]) => `<div><div style="height:22mm;border-radius:1.2mm;background:${g}"></div><div class="cap">${n}</div></div>`).join('')}</div></div>
    <div><h3>Textures compatibles</h3><div class="grid g3" style="gap:3mm">${[['enduit', 'Enduit minéral'], ['travertin', 'Travertin'], ['papier', 'Papier craie'], ['espresso', 'Espresso'], ['cuir', 'Cuir grenat'], ['bois', 'Bois brun']].map(([k, n]) => `<div><img src="../textures/${k}.jpg" style="width:100%;height:24mm;object-fit:cover;border-radius:1.2mm"><div class="cap">${n}</div></div>`).join('')}</div>
    <h3 style="margin-top:6mm">Fonds types</h3><div class="grid g3" style="gap:3mm">${[[C.craie, C.espresso, 'Fond craie'], [C.espresso, C.craie, 'Fond espresso'], [C.grenat, C.ivoire, 'Fond grenat (rare)']].map(([b, f, n]) => `<div style="background:${b};color:${f};border-radius:1.2mm;padding:4mm;height:26mm"><div style="font:500 12pt/1.05 Fraunces">Ce que cela implique</div>${mark('underline', 60, 8, 'display:block;margin-top:2mm', b === C.grenat ? C.craie : C.grenat)}<div style="font:600 6pt Manrope;letter-spacing:.14em;margin-top:2mm">${n.toUpperCase()}</div></div>`).join('')}</div></div></div>`, { chap })
  page('esp', `${K('Typographies · proposition')}<h1>Une voix éditoriale, une voix nette</h1>
    <div style="display:grid;grid-template-columns:1.2fr 1fr;gap:12mm;margin-top:8mm">
    <div><h3>Titres — Fraunces 500</h3><div style="font:500 40pt/1 Fraunces;letter-spacing:-.02em">Une décision n’est jamais ${U('isolée')}.</div><p class="cap" style="margin-top:4mm">Serif contemporaine, affirmée, chaleureuse. Interlettrage −2 %. Corps : 40 à 120 px sur les visuels.</p>
    <h3 style="margin-top:8mm">Citations — Fraunces italique</h3><div style="font:400 italic 22pt/1.2 Fraunces;color:#C7B39B">« Une société à l’étranger, c’est moins d’impôts. »</div></div>
    <div><h3>Texte — Inter 400 / 600</h3><p style="font-size:12pt;color:#E7DED2">Substance, lieu de direction, résidence du dirigeant : ce qui décide vraiment. Chaque terme technique est expliqué en une phrase.</p>
    <h3 style="margin-top:8mm">Rubriques — Manrope 700, capitales, +24 %</h3><div style="font:700 11pt Manrope;letter-spacing:.24em;color:#C7B39B">THE REALITY CHECK · LE POINT DE CONTRÔLE</div>
    <h3 style="margin-top:8mm">Annotations — Instrument Serif italique</h3><div style="font:italic 400 20pt 'Instrument Serif';color:#E7DED2">lieu de direction ?</div><p class="cap">Réservée aux annotations « manuscrites » du carnet et des documents.</p></div></div>
    <p class="cap" style="margin-top:8mm">Toutes les polices sont sous licence SIL Open Font License (fichiers dans brand-assets/typefaces).</p>`, { chap, bg: TEX.espresso() })

  /* ======================= CH8 RED MARK ======================= */
  chapter('The Red Mark', 'Un trait grenat qui marque le point qui change la compréhension d’une situation. Un signe, pas un logo.', null, 'craie')
  page('craie', `${K('The Red Mark · concept')}<div style="display:grid;grid-template-columns:1fr 1fr;gap:12mm;margin-top:8mm;align-items:center">
    <div><div style="font:500 44pt/1 Fraunces;letter-spacing:-.02em">Le point qui change la ${U('lecture.')}</div>
    <p class="lead">${tag.prop}Le trait grenat n’est jamais décoratif. Il apparaît à un seul endroit par support : sur le mot, le chiffre ou la ligne qui change la compréhension. Il traduit visuellement la méthode « Vérifier ».</p>
    <ul class="l" style="margin-top:5mm">${['Un seul trait par visuel', 'Toujours sur une information, jamais dans le vide', 'Tracé à la main : il garde une irrégularité humaine', 'Grenat #702B40 uniquement (ou craie sur fond grenat)'].map((x) => `<li>${x}</li>`).join('')}</ul></div>
    <div><img src="../mockups/instagram/03-reality-check-societe.jpg" style="width:92mm;margin:auto;box-shadow:0 10mm 20mm -10mm rgba(48,40,32,.5)"></div></div>`, { chap })
  const VAR = [['horizontal', 'Trait horizontal', 'Souligner le mot clé d’un titre.', 150, 24], ['vertical', 'Trait vertical', 'Marquer une rubrique, une marge, une liste.', 16, 90], ['annotation', 'Trait d’annotation', 'Pointer une ligne d’un document.', 170, 40], ['circle', 'Cercle partiel', 'Entourer un chiffre ou un critère.', 150, 80], ['bracket', 'Encadrement partiel', 'Isoler un paragraphe ou une donnée.', 30, 90], ['signature', 'Signature document', 'Fin de note, documents, cartes.', 150, 40]]
  page('craie', `${K('The Red Mark · déclinaisons')}<h1>Six déclinaisons, une animation</h1>
    <div class="grid g3" style="margin-top:7mm;row-gap:6mm">${VAR.map(([v, n, u, w, h]) => `<div style="display:flex;gap:5mm;align-items:center"><div style="width:52mm;height:28mm;background:#fff;border-radius:1.2mm;display:flex;align-items:center;justify-content:center">${mark(v, w, h)}</div><div><h4 style="font:500 12pt Fraunces">${n}</h4><p style="font-size:8.6pt">${u}</p></div></div>`).join('')}</div>
    <h3 style="margin-top:8mm">Animation du trait — 600 ms, accélération douce, aucune autre animation simultanée</h3>
    <div class="grid g5" style="gap:3mm">${[1, 2, 3, 4, 5].map((i) => `<img src="../mockups/red-mark/animation-${i}.jpg" style="width:100%;border-radius:1mm">`).join('')}</div>`, { chap })
  page('craie', `${K('The Red Mark · règles d’utilisation')}<h1>Ce qu’il faut faire, ce qu’il faut éviter</h1>
    <div class="grid g2" style="margin-top:7mm;gap:12mm"><div><h3>Règles</h3><ul class="l">${['Un trait par visuel ; deux maximum sur une slide de démonstration', 'Longueur : celle du mot ou de la ligne concernée, jamais plus de 110 %', 'Épaisseur : environ 20 % de la hauteur du texte souligné', 'Grenat sur fond clair ; craie sur fond grenat ; grenat sur espresso pour les grands formats', 'Le trait arrive en dernier dans les animations', 'Il doit pouvoir s’expliquer : « ce point change la lecture parce que… »'].map((x) => `<li>→ ${x}</li>`).join('')}</ul></div>
    <div><h3>Mauvaises utilisations</h3><div class="grid g3" style="gap:3mm">${[['Plusieurs traits', `<div style="font:500 13pt Fraunces">${U('Trop')} de ${U('traits')}</div>`], ['En décor', `${mark('circle', 110, 50)}`], ['Autre couleur', `${mark('horizontal', 110, 18, '', '#2F6FD6')}`], ['Logo figé', `<div style="font:700 9pt Manrope;letter-spacing:.2em">TIZIANA</div>${mark('horizontal', 110, 18)}`], ['Sur un visage', `<div style="width:24mm;height:16mm;border-radius:50%;background:#C7B39B;display:flex;align-items:center;justify-content:center">${mark('horizontal', 70, 12)}</div>`], ['Mot sans importance', `<div style="font:500 12pt Fraunces">Le ${U('de')} titre</div>`]].map(([n, h]) => `<div style="background:#fff;border-radius:1.2mm;padding:3mm;height:30mm;position:relative;display:flex;align-items:center;justify-content:center;flex-direction:column">${h}<div style="position:absolute;left:2mm;bottom:2mm;font:700 6pt Manrope;color:#702B40">✕ ${n.toUpperCase()}</div></div>`).join('')}</div></div></div>`, { chap })

